WITH enriched AS (SELECT id, order_id, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY quantity, id) AS seq_no, DENSE_RANK() OVER (PARTITION BY order_id, product_id ORDER BY unit_price NULLS LAST) AS unit_price_dense_rank, ROW_NUMBER() OVER w_ordered AS event_seq FROM order_items WINDOW w_ordered AS (PARTITION BY order_id ORDER BY quantity DESC, id)) SELECT CASE WHEN seq_no >= 9 THEN 'HIGH' ELSE 'LOW' END AS seq_no_tier, COUNT(*) AS num_rows, COUNT(*) AS num_rows_2, COUNT(*) AS event_count, APPROX_PERCENTILE(seq_no, ARRAY(0.25, 0.5, 0.75)) AS seq_no_quartiles, COUNT(*) AS num_rows_3, GROUPING_ID() AS grouping_level FROM enriched GROUP BY CUBE (CASE WHEN seq_no >= 9 THEN 'HIGH' ELSE 'LOW' END) HAVING event_count > 1
